 static void Run(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists("Evidence/hunter-torch-20261030/raised-fix.txt"))return;var pose=Object.FindObjectOfType<HunterTorchPose>();if(!pose)return;var a=pose.bridge.animator;var c=(AnimatorController)a.runtimeAnimatorController;var layers=c.layers;layers[pose.layer].iKPass=true;layers[pose.layer].avatarMask.SetHumanoidBodyPartActive(AvatarMaskBodyPart.LeftHandIK,true);EditorUtility.SetDirty(layers[pose.layer].avatarMask);c.layers=layers;var ik=a.gameObject.AddComponent<HunterTorchHandIK>();ik.pose=pose;
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Viking Village/Prefabs/Props/pf_torch_fire_01.prefab");var originals=source.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().ToArray();var torch=a.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Hunter Left Torch");
