 foreach(var ps in torch.GetComponentsInChildren<ParticleSystem>(true)){var m=ps.main;m.scalingMode=ParticleSystemScalingMode.Hierarchy;}
 EditorUtility.SetDirty(c);EditorSceneManager.SaveScene(pose.gameObject.scene);PrefabUtility.SaveAsPrefabAsset(pose.gameObject,"Assets/Demo/Characters/Hunter/Torch/Hunter_TorchPlayer.prefab");AssetDatabase.SaveAssets();File.WriteAllText("Evidence/hunter-torch-20261030/raised-fix.txt","Left-hand IK target local (-.40,1.55,.46), left elbow hint; attack keeps hold; texture copied from actual URP _BaseMap.\n");}
